const personLast10 = last10(phoneRaw);
const isVerified = identityRows.some(r => {
  const sameLead = String(r.lead_id ?? "") !== "" && String(r.lead_id) === String(person.id ?? "");
  const samePhone = personLast10 !== "" && last10(r.phone) === personLast10;
