const daysSinceTrash = Number.isFinite(trashDateMs) ? (Date.now() - trashDateMs) / 86400000 : Infinity;
let trashBlock = null;
if (tagsLower.includes("permanent trash")) trashBlock = "trash_permanent";
else if (tagsLower.includes("denied credit")) { if (daysSinceTrash <= 365) trashBlock = "trash_denied_credit"; }
else if (tagsLower.includes("no response trash")) { if (daysSinceTrash <= 90) trashBlock = "trash_temporary"; } // TRASH_TAG_RENAME_MARKER: real tag is "No Response Trash"
// ── TRASH_FALLTHROUGH_MARKER: stage fallback must run whenever no TAG produced a block.
