  .replace(/\{\{greeting\}\}/g, "Hello!")
  .replace(/\{\{first_name\}\}/g, person.firstName || person.name || "")
  .replace(/\{\{property_address\}\}/g, propertyAddress)
  .replace(/\{\{cal_link\}\}/g, enrichedCalLink)
  .replace(/\{\{apply_link\}\}/g, settings.apply_link || "");

